  Low
  Medium
  High
  Extreme
}

pub type AdaptiveKANLayer {
  AdaptiveKANLayer(
    input_dim: Int,
    output_dim: Int,
    base_grid: Int,
    current_grid: Int,
    spline_degree: Int,
    hierarchical_levels: Int,
    weights: Matrix,
    control_points: List(Matrix),
    complexity_threshold: Float,
  )
}

pub fn matrix_random(rows: Int, cols: Int) -> Matrix {
  let size = rows * cols
  let data = list.map(list.range(0, size - 1), fn(_) {
    float.random() *. 2.0 -. 1.0
  })
  Matrix(rows: rows, cols: cols, data: data)
}

pub fn matrix_get(matrix: Matrix, row: Int, col: Int) -> Result(Float, Nil) {
  case row < 0 || row >= matrix.rows || col < 0 || col >= matrix.cols {
    True -> Error(Nil)
    False -> {
      let index = row * matrix.cols + col
      list.at(matrix.data, index)
    }
  }
}

pub fn matrix_set(matrix: Matrix, row: Int, col: Int, value: Float) -> Matrix {
  case row < 0 || row >= matrix.rows || col < 0 || col >= matrix.cols {
    True -> matrix
    False -> {
      let index = row * matrix.cols + col
      let new_data = list.index_map(matrix.data, fn(val, idx) {
        case idx == index {
          True -> value
          False -> val
        }
      })
      Matrix(..matrix, data: new_data)
    }
  }
}

pub fn matrix_multiply(a: Matrix, b: Matrix) -> Matrix {
  let result_rows = a.rows
  let result_cols = b.cols
  let result_data = list.flat_map(list.range(0, result_rows - 1), fn(i) {
    list.map(list.range(0, result_cols - 1), fn(j) {
      let sum = list.fold(list.range(0, a.cols - 1), 0.0, fn(acc, k) {
        let a_val = result.unwrap(matrix_get(a, i, k), 0.0)
        let b_val = result.unwrap(matrix_get(b, k, j), 0.0)
        acc +. a_val *. b_val
      })
      sum
    })
  })
  Matrix(rows: result_rows, cols: result_cols, data: result_data)
}

pub fn matrix_map_with_index(matrix: Matrix, f: fn(Float, Int, Int) -> Float) -> Matrix {
  let new_data = list.index_map(matrix.data, fn(val, idx) {
    let row = idx / matrix.cols
    let col = idx - row * matrix.cols
    f(val, row, col)
  })
  Matrix(..matrix, data: new_data)
}

pub fn matrix_variance(matrix: Matrix) -> Float {
  let n = int.to_float(list.length(matrix.data))
  case n <=. 0.0 {
    True -> 0.0
    False -> {
      let mean = list.fold(matrix.data, 0.0, fn(acc, x) { acc +. x }) /. n
      let variance = list.fold(matrix.data, 0.0, fn(acc, x) {
        let diff = x -. mean
        acc +. diff *. diff
      }) /. n
      variance
    }
  }
}

pub fn matrix_entropy(matrix: Matrix) -> Float {
  let min_val = result.unwrap(list.reduce(matrix.data, float.min), 0.0)
  let max_val = result.unwrap(list.reduce(matrix.data, float.max), 1.0)
  let range = max_val -. min_val
  case range <=. 0.0 {
    True -> 0.0
    False -> {
      let bins = 10
      let bin_counts = list.fold(list.range(0, bins - 1), [], fn(acc, _) {
        [0, ..acc]
      })
      let total = int.to_float(list.length(matrix.data))
      let updated_counts = list.fold(matrix.data, bin_counts, fn(counts, val) {
        let normalized = { val -. min_val } /. range
        let bin_idx = case float.truncate(normalized *. int.to_float(bins)) {
          Ok(idx) -> case idx >= bins {
            True -> bins - 1
            False -> case idx < 0 {
              True -> 0
              False -> idx
            }
          }
          Error(_) -> 0
        }
        list.index_map(counts, fn(count, idx) {
          case idx == bin_idx {
            True -> count + 1
            False -> count
          }
        })
      })
      let entropy = list.fold(updated_counts, 0.0, fn(acc, count) {
        case count > 0 {
          True -> {
            let p = int.to_float(count) /. total
            let log_p = float.logarithm(p)
            case log_p {
              Ok(lp) -> acc -. p *. lp
              Error(_) -> acc
            }
          }
          False -> acc
        }
      })
      entropy
    }
  }
}

pub fn matrix_spectral_norm(matrix: Matrix) -> Float {
  let max_val = result.unwrap(
    list.reduce(list.map(matrix.data, float.absolute_value), float.max),
    1.0,
  )
  max_val
}

pub fn create_adaptive_layer(
  input_dim: Int,
  output_dim: Int,
  base_grid: Int,
  hierarchical_levels: Int,
) -> AdaptiveKANLayer {
  let control_points = list.map(list.range(0, hierarchical_levels - 1), fn(_level) {
    matrix_random(output_dim, base_grid + 1)
  })

  AdaptiveKANLayer(
    input_dim: input_dim,
    output_dim: output_dim,
    base_grid: base_grid,
    current_grid: base_grid,
    spline_degree: 3,
    hierarchical_levels: hierarchical_levels,
    weights: matrix_random(output_dim, input_dim),
    control_points: control_points,
    complexity_threshold: 0.5,
  )
}

pub fn compute_input_complexity(input: Matrix) -> Float {
  let variance = matrix_variance(input)
  let entropy = matrix_entropy(input)
  let spectral_norm = matrix_spectral_norm(input)

  let complexity_score = variance *. 0.3 +. entropy *. 0.4 +. spectral_norm *. 0.3
  complexity_score
}

pub fn adapt_grid_size(layer: AdaptiveKANLayer, complexity: Float) -> AdaptiveKANLayer {
  let new_grid = case complexity {
    c if c <. 0.3 -> layer.base_grid
    c if c <. 0.6 -> layer.base_grid + 5
    c if c <. 0.85 -> layer.base_grid + 10
    _ -> layer.base_grid + 20
  }

  AdaptiveKANLayer(..layer, current_grid: new_grid)
}

pub fn hierarchical_spline_eval(
  x: Float,
  control_points_hierarchy: List(Matrix),
  grid: Int,
  level: Int,
) -> Float {
  case level {
    0 -> b_spline_basis_eval(x, grid, 3)
    _ -> {
      let coarse = hierarchical_spline_eval(x, control_points_hierarchy, grid / 2, level - 1)
      let fine = b_spline_basis_eval(x, grid, 3)
      coarse *. 0.6 +. fine *. 0.4
    }
  }
}

pub fn b_spline_basis_eval(x: Float, grid: Int, degree: Int) -> Float {
  let knots = list.map(list.range(0, grid), fn(i) {
    int.to_float(i) /. int.to_float(grid - 1)
  })

  let normalized_x = case x <. 0.0 {
    True -> 0.0
    False -> case x >. 1.0 {
      True -> 1.0
      False -> x
    }
  }

  case degree {
    0 -> {
      case find_knot_interval(normalized_x, knots) {
        Ok(_) -> 1.0
        Error(_) -> 0.0
      }
    }
    _ -> {
      let basis_sum = list.fold(list.range(0, grid - degree), 0.0, fn(sum, i) {
        let alpha = compute_alpha(normalized_x, knots, i, degree)
        sum +. alpha
      })
      basis_sum /. int.to_float(grid)
    }
  }
}

pub fn find_knot_interval(x: Float, knots: List(Float)) -> Result(Int, Nil) {
  list.index_fold(knots, Error(Nil), fn(acc, knot, idx) {
    case acc {
      Ok(_) -> acc
      Error(_) -> {
        case list.at(knots, idx + 1) {
          Ok(next_knot) -> case x >=. knot && x <. next_knot {
            True -> Ok(idx)
            False -> Error(Nil)
          }
          _ -> Error(Nil)
        }
      }
    }
  })
}

pub fn compute_alpha(x: Float, knots: List(Float), i: Int, degree: Int) -> Float {
  let k_i = result.unwrap(list.at(knots, i), 0.0)
  let k_i_deg = result.unwrap(list.at(knots, i + degree), 1.0)

  let denom = k_i_deg -. k_i
  case denom >. 0.0001 {
    True -> { x -. k_i } /. denom
    False -> 0.0
  }
}

pub fn forward_adaptive(layer: AdaptiveKANLayer, input: Matrix) -> Matrix {
  let complexity = compute_input_complexity(input)
  let adapted_layer = adapt_grid_size(layer, complexity)

  let result = matrix_map_with_index(input, fn(val, i, j) {
    let hierarchical_result = hierarchical_spline_eval(
      val,
      adapted_layer.control_points,
      adapted_layer.current_grid,
      adapted_layer.hierarchical_levels - 1,
    )
    hierarchical_result
  })

  matrix_multiply(adapted_layer.weights, result)
}

pub fn train_layer(
  layer: AdaptiveKANLayer,
  input_batch: List(Matrix),
  target_batch: List(Matrix),
  learning_rate: Float,
  epochs: Int,
) -> AdaptiveKANLayer {
  case epochs {
    0 -> layer
    _ -> {
      let updated_layer = list.fold(
        list.zip(input_batch, target_batch),
        layer,
        fn(current_layer, pair) {
          let input = pair.0
          let target = pair.1
          let output = forward_adaptive(current_layer, input)
          let error_matrix = Matrix(
            rows: output.rows,
            cols: output.cols,
            data: list.zip(output.data, target.data)
              |> list.map(fn(vals) { vals.0 -. vals.1 }),
          )
          let gradient_scale = 2.0 *. learning_rate /. int.to_float(list.length(input_batch))
          let new_weights = Matrix(
            rows: current_layer.weights.rows,
            cols: current_layer.weights.cols,
            data: list.zip(current_layer.weights.data, error_matrix.data)
              |> list.map(fn(vals) { vals.0 -. gradient_scale *. vals.1 }),
          )
          AdaptiveKANLayer(..current_layer, weights: new_weights)
        },
      )
      train_layer(updated_layer, input_batch, target_batch, learning_rate, epochs - 1)
    }
  }
}

pub fn compute_loss(layer: AdaptiveKANLayer, input: Matrix, target: Matrix) -> Float {
  let output = forward_adaptive(layer, input)
  list.fold(
    list.zip(output.data, target.data),
    0.0,
    fn(acc, pair) {
      let diff = pair.0 -. pair.1
      acc +. diff *. diff
    },
  ) /. int.to_float(list.length(output.data))
}
