import gleam/io
import gleam/int
import gleam/float
import gleam/list
import gleam/result
import gleam/string
import gleam/dict
import gleam/json
import gleam/dynamic/decode

pub type Matrix {
  Matrix(rows: Int, cols: Int, data: List(Float))
}

pub type KANLayer {
  KANLayer(
    input_dim: Int,
    output_dim: Int,
    grid_size: Int,
    spline_degree: Int,
    weights: Matrix,
    spline_coefficients: List(List(Float)),
    knots: List(Float),
  )
}

pub type KANNetwork {
  KANNetwork(
    layers: List(KANLayer),
    input_dim: Int,
    output_dim: Int,
    learning_rate: Float,
  )
}

pub type FileError {
  WriteError(String)
  ReadError(String)
  ParseError(String)
}

pub fn matrix_random(rows: Int, cols: Int, seed: Int) -> Matrix {
  let size = rows * cols
  let data = list.index_map(list.range(0, size - 1), fn(val, idx) {
    let hash = int.bitwise_exclusive_or(seed + idx, val * 2654435761)
    let normalized = int.to_float(int.bitwise_and(hash, 16777215)) /. 16777216.0
    normalized *. 2.0 -. 1.0
  })
  Matrix(rows: rows, cols: cols, data: data)
}

pub fn matrix_zeros(rows: Int, cols: Int) -> Matrix {
  let size = rows * cols
  let data = list.map(list.range(0, size - 1), fn(_) { 0.0 })
  Matrix(rows: rows, cols: cols, data: data)
}

pub fn matrix_get(matrix: Matrix, row: Int, col: Int) -> Result(Float, Nil) {
  case row < 0 || row >= matrix.rows || col < 0 || col >= matrix.cols {
    True -> Error(Nil)
    False -> {
      let index = row * matrix.cols + col
      list.at(matrix.data, index)
    }
  }
}

pub fn matrix_multiply(a: Matrix, b: Matrix) -> Matrix {
  let result_rows = a.rows
  let result_cols = b.cols
  let result_data = list.flat_map(list.range(0, result_rows - 1), fn(i) {
    list.map(list.range(0, result_cols - 1), fn(j) {
      list.fold(list.range(0, a.cols - 1), 0.0, fn(acc, k) {
        let a_val = result.unwrap(matrix_get(a, i, k), 0.0)
        let b_val = result.unwrap(matrix_get(b, k, j), 0.0)
        acc +. a_val *. b_val
      })
    })
  })
  Matrix(rows: result_rows, cols: result_cols, data: result_data)
}

pub fn create_kan_layer(
  input_dim: Int,
  output_dim: Int,
  grid_size: Int,
  spline_degree: Int,
  seed: Int,
) -> KANLayer {
  let weights = matrix_random(output_dim, input_dim, seed)
  let num_coeffs = grid_size + spline_degree
  let spline_coefficients = list.map(
    list.range(0, output_dim * input_dim - 1),
    fn(idx) {
      list.index_map(list.range(0, num_coeffs - 1), fn(val, coeff_idx) {
        let hash = int.bitwise_exclusive_or(seed + idx + coeff_idx, val * 2654435761)
        let normalized = int.to_float(int.bitwise_and(hash, 16777215)) /. 16777216.0
        normalized *. 0.2 -. 0.1
      })
    },
  )
  let knots = list.map(list.range(0, grid_size + 2 * spline_degree), fn(i) {
    case i < spline_degree {
      True -> 0.0
      False -> case i >= grid_size + spline_degree {
        True -> 1.0
        False -> int.to_float(i - spline_degree) /. int.to_float(grid_size)
      }
    }
  })
  KANLayer(
    input_dim: input_dim,
    output_dim: output_dim,
    grid_size: grid_size,
    spline_degree: spline_degree,
    weights: weights,
    spline_coefficients: spline_coefficients,
    knots: knots,
  )
}

pub fn create_kan_network(
  layer_sizes: List(Int),
  grid_size: Int,
  spline_degree: Int,
  learning_rate: Float,
  seed: Int,
) -> KANNetwork {
  let input_dim = result.unwrap(list.first(layer_sizes), 1)
  let output_dim = result.unwrap(list.last(layer_sizes), 1)
  let layers = list.window_by_2(layer_sizes)
    |> list.index_map(fn(pair, idx) {
      create_kan_layer(pair.0, pair.1, grid_size, spline_degree, seed + idx)
    })
  KANNetwork(
    layers: layers,
    input_dim: input_dim,
    output_dim: output_dim,
    learning_rate: learning_rate,
  )
}

pub fn b_spline_basis(x: Float, i: Int, k: Int, knots: List(Float)) -> Float {
  case k {
    0 -> {
      let ki = result.unwrap(list.at(knots, i), 0.0)
      let ki1 = result.unwrap(list.at(knots, i + 1), 1.0)
      case x >=. ki && x <. ki1 {
        True -> 1.0
        False -> case i == list.length(knots) - 2 && x ==. ki1 {
          True -> 1.0
          False -> 0.0
        }
      }
    }
    _ -> {
      let ki = result.unwrap(list.at(knots, i), 0.0)
      let kik = result.unwrap(list.at(knots, i + k), ki + 1.0)
      let ki1 = result.unwrap(list.at(knots, i + 1), ki)
      let kik1 = result.unwrap(list.at(knots, i + k + 1), kik + 1.0)
      let left_denom = kik -. ki
      let right_denom = kik1 -. ki1
      let left_term = case left_denom >. 0.0001 {
        True -> { x -. ki } /. left_denom *. b_spline_basis(x, i, k - 1, knots)
        False -> 0.0
      }
      let right_term = case right_denom >. 0.0001 {
        True -> { kik1 -. x } /. right_denom *. b_spline_basis(x, i + 1, k - 1, knots)
        False -> 0.0
      }
      left_term +. right_term
    }
  }
}

pub fn evaluate_spline(x: Float, coeffs: List(Float), knots: List(Float), degree: Int) -> Float {
  let num_basis = list.length(coeffs)
  list.fold(list.range(0, num_basis - 1), 0.0, fn(acc, i) {
    let basis_val = b_spline_basis(x, i, degree, knots)
    let coeff = result.unwrap(list.at(coeffs, i), 0.0)
    acc +. coeff *. basis_val
  })
}

pub fn forward_layer(layer: KANLayer, input: Matrix) -> Matrix {
  let transformed_data = list.index_map(input.data, fn(x, idx) {
    let row = idx / input.cols
    let col = idx - row * input.cols
    let neuron_idx = row * layer.input_dim + col
    let coeffs = result.unwrap(list.at(layer.spline_coefficients, neuron_idx), [])
    let normalized_x = case x <. 0.0 {
      True -> 0.0
      False -> case x >. 1.0 {
        True -> 1.0
        False -> x
      }
    }
    evaluate_spline(normalized_x, coeffs, layer.knots, layer.spline_degree)
  })
  let transformed_matrix = Matrix(rows: input.rows, cols: input.cols, data: transformed_data)
  matrix_multiply(layer.weights, transformed_matrix)
}

pub fn forward(network: KANNetwork, input: Matrix) -> Matrix {
  list.fold(network.layers, input, fn(current_input, layer) {
    forward_layer(layer, current_input)
  })
}

pub fn matrix_to_json(matrix: Matrix) -> json.Json {
  json.object([
    #("rows", json.int(matrix.rows)),
    #("cols", json.int(matrix.cols)),
