pub fn train_step(network: KANNetwork, input: Matrix, target: Matrix) -> KANNetwork {
  let output = forward(network, input)
  let errors = Matrix(
    rows: output.rows,
    cols: output.cols,
    data: list.zip(output.data, target.data)
      |> list.map(fn(pair) { pair.0 -. pair.1 }),
  )
  let updated_layers = list.map(network.layers, fn(layer) {
    let gradient_scale = network.learning_rate /. int.to_float(list.length(input.data))
    let updated_weights = Matrix(
      rows: layer.weights.rows,
      cols: layer.weights.cols,
      data: list.zip(layer.weights.data, errors.data)
        |> list.map(fn(pair) { pair.0 -. gradient_scale *. pair.1 }),
    )
    KANLayer(..layer, weights: updated_weights)
  })
  KANNetwork(..network, layers: updated_layers)
}

pub fn compute_loss(network: KANNetwork, input: Matrix, target: Matrix) -> Float {
  let output = forward(network, input)
  list.fold(
    list.zip(output.data, target.data),
    0.0,
    fn(acc, pair) {
      let diff = pair.0 -. pair.1
      acc +. diff *. diff
    },
  ) /. int.to_float(list.length(output.data))
}

