pub type Matrix {
  Matrix(rows: Int, cols: Int, data: List(Float))
}

pub fn matrix_random(rows: Int, cols: Int, seed: Int) -> Matrix {
  let size = rows * cols
  let data = list.index_map(list.range(0, size - 1), fn(val, idx) {
    let hash = int.bitwise_exclusive_or(seed + idx, val * 2654435761)
    let normalized = int.to_float(int.bitwise_and(hash, 16777215)) /. 16777216.0
    normalized *. 2.0 -. 1.0
  })
  Matrix(rows: rows, cols: cols, data: data)
}

pub fn matrix_zeros(rows: Int, cols: Int) -> Matrix {
  let size = rows * cols
  let data = list.map(list.range(0, size - 1), fn(_) { 0.0 })
  Matrix(rows: rows, cols: cols, data: data)
}

pub fn matrix_ones(rows: Int, cols: Int) -> Matrix {
  let size = rows * cols
  let data = list.map(list.range(0, size - 1), fn(_) { 1.0 })
  Matrix(rows: rows, cols: cols, data: data)
}

pub fn matrix_add(a: Matrix, b: Matrix) -> Matrix {
  case a.rows == b.rows && a.cols == b.cols {
    True -> {
      let new_data = list.zip(a.data, b.data)
        |> list.map(fn(pair) { pair.0 +. pair.1 })
      Matrix(rows: a.rows, cols: a.cols, data: new_data)
    }
    False -> a
  }
}

pub fn matrix_subtract(a: Matrix, b: Matrix) -> Matrix {
  case a.rows == b.rows && a.cols == b.cols {
    True -> {
      let new_data = list.zip(a.data, b.data)
        |> list.map(fn(pair) { pair.0 -. pair.1 })
      Matrix(rows: a.rows, cols: a.cols, data: new_data)
    }
    False -> a
  }
}

pub fn matrix_multiply(a: Matrix, b: Matrix) -> Matrix {
  case a.cols == b.rows {
    True -> {
      let result_rows = a.rows
      let result_cols = b.cols
      let result_data = list.flat_map(list.range(0, result_rows - 1), fn(i) {
        list.map(list.range(0, result_cols - 1), fn(j) {
          list.fold(list.range(0, a.cols - 1), 0.0, fn(acc, k) {
            let a_idx = i * a.cols + k
            let b_idx = k * b.cols + j
            let a_val = result.unwrap(list.at(a.data, a_idx), 0.0)
            let b_val = result.unwrap(list.at(b.data, b_idx), 0.0)
            acc +. a_val *. b_val
          })
        })
      })
      Matrix(rows: result_rows, cols: result_cols, data: result_data)
    }
    False -> matrix_zeros(a.rows, b.cols)
  }
}

pub fn matrix_scale(matrix: Matrix, scalar: Float) -> Matrix {
  let new_data = list.map(matrix.data, fn(val) { val *. scalar })
  Matrix(rows: matrix.rows, cols: matrix.cols, data: new_data)
}

pub fn matrix_get(matrix: Matrix, row: Int, col: Int) -> Result(Float, Nil) {
  case row < 0 || row >= matrix.rows || col < 0 || col >= matrix.cols {
    True -> Error(Nil)
    False -> {
      let index = row * matrix.cols + col
      list.at(matrix.data, index)
    }
  }
}

pub fn matrix_set(matrix: Matrix, row: Int, col: Int, value: Float) -> Matrix {
  case row < 0 || row >= matrix.rows || col < 0 || col >= matrix.cols {
    True -> matrix
    False -> {
      let index = row * matrix.cols + col
