        case idx == index {
          True -> value
          False -> val
        }
      })
      Matrix(rows: matrix.rows, cols: matrix.cols, data: new_data)
    }
  }
}

pub fn matrix_transpose(matrix: Matrix) -> Matrix {
  let new_data = list.flat_map(list.range(0, matrix.cols - 1), fn(col) {
    list.map(list.range(0, matrix.rows - 1), fn(row) {
      result.unwrap(matrix_get(matrix, row, col), 0.0)
    })
  })
  Matrix(rows: matrix.cols, cols: matrix.rows, data: new_data)
}

pub fn matrix_mean(matrix: Matrix) -> Float {
  let total = list.fold(matrix.data, 0.0, fn(acc, val) { acc +. val })
  let count = int.to_float(list.length(matrix.data))
  case count >. 0.0 {
    True -> total /. count
    False -> 0.0
  }
}

