}

pub fn sized_chunk(lst: List(a), chunk_size: Int) -> List(List(a)) {
  case chunk_size <= 0 {
    True -> [lst]
    False -> sized_chunk_helper(lst, chunk_size, [])
  }
}

fn sized_chunk_helper(lst: List(a), chunk_size: Int, acc: List(List(a))) -> List(List(a)) {
  case list.length(lst) {
    0 -> list.reverse(acc)
    _ -> {
      let chunk = list.take(lst, chunk_size)
      let rest = list.drop(lst, chunk_size)
      sized_chunk_helper(rest, chunk_size, [chunk, ..acc])
    }
  }
}

pub fn distribute_batch(batch: List(Matrix), workers: Int) -> List(List(Matrix)) {
  let chunk_size = case workers > 0 {
    True -> {
      let len = list.length(batch)
      case len / workers {
        0 -> 1
        n -> n
      }
    }
    False -> list.length(batch)
  }
  case chunk_size > 0 {
    True -> sized_chunk(batch, chunk_size)
    False -> [batch]
  }
}

