  case list.first(grads) {
    Ok(first) -> list.fold(list.drop(grads, 1), first, matrix_add)
    Error(_) -> matrix_ones(1, 1)
  }
}

pub fn parallel_process_batch(
  batch: List(Matrix),
  workers: Int,
  process_fn: fn(Matrix) -> Matrix,
) -> List(Matrix) {
  let distributed = distribute_batch(batch, workers)
  list.flat_map(distributed, fn(chunk) {
    list.map(chunk, process_fn)
  })
}

pub fn compute_batch_gradients(
  batch: List(Matrix),
  targets: List(Matrix),
  weights: Matrix,
) -> Matrix {
  let gradients = list.zip(batch, targets)
    |> list.map(fn(pair) {
      let input = pair.0
      let target = pair.1
      let prediction = matrix_multiply(weights, input)
      let error = matrix_subtract(prediction, target)
      let gradient = matrix_multiply(error, matrix_transpose(input))
      gradient
    })
  aggregate_grads(gradients)
}

pub fn distributed_sgd_step(
  batch: List(Matrix),
  targets: List(Matrix),
  weights: Matrix,
  learning_rate: Float,
  workers: Int,
) -> Matrix {
  let distributed_batches = distribute_batch(batch, workers)
  let distributed_targets = distribute_batch(targets, workers)
  let worker_gradients = list.zip(distributed_batches, distributed_targets)
    |> list.map(fn(pair) {
      compute_batch_gradients(pair.0, pair.1, weights)
    })
  let aggregated_gradient = aggregate_grads(worker_gradients)
  let scaled_gradient = matrix_scale(aggregated_gradient, learning_rate)
  matrix_subtract(weights, scaled_gradient)
}

pub fn train_distributed(
  training_data: List(Matrix),
  training_targets: List(Matrix),
  initial_weights: Matrix,
  learning_rate: Float,
  epochs: Int,
  workers: Int,
  batch_size: Int,
) -> Matrix {
  case epochs {
    0 -> initial_weights
    _ -> {
      let batches = sized_chunk(training_data, batch_size)
      let target_batches = sized_chunk(training_targets, batch_size)
      let updated_weights = list.fold(
        list.zip(batches, target_batches),
        initial_weights,
        fn(current_weights, batch_pair) {
          distributed_sgd_step(
            batch_pair.0,
            batch_pair.1,
            current_weights,
            learning_rate,
            workers,
          )
        },
      )
      train_distributed(
        training_data,
        training_targets,
        updated_weights,
        learning_rate,
        epochs - 1,
        workers,
        batch_size,
      )
    }
  }
}

pub fn compute_loss(predictions: List(Matrix), targets: List(Matrix)) -> Float {
  let squared_errors = list.zip(predictions, targets)
    |> list.map(fn(pair) {
      let diff = matrix_subtract(pair.0, pair.1)
      let squared = matrix_map(diff, fn(x) { x *. x })
      matrix_mean(squared)
    })
  let total_loss = list.fold(squared_errors, 0.0, fn(acc, loss) { acc +. loss })
  let num_samples = int.to_float(list.length(predictions))
  case num_samples >. 0.0 {
    True -> total_loss /. num_samples
    False -> 0.0
  }
}

pub fn main() {
