  let batch_size = 100
  let workers = 4
  let batch = list.index_map(list.range(0, batch_size - 1), fn(_, idx) {
    matrix_random(1, 10, seed + idx)
  })
  let distributed = distribute_batch(batch, workers)
  io.println("Distributed batch count: " <> int.to_string(list.length(distributed)))
  let targets = list.index_map(list.range(0, batch_size - 1), fn(_, idx) {
