  let predictions = list.map(batch, fn(input) {
    matrix_multiply(trained_weights, input)
  })
  let loss = compute_loss(predictions, targets)
  io.println("Final training loss: " <> float.to_string(loss))
  let test_input = matrix_random(1, 10, seed + 9999)
  let test_output = matrix_multiply(trained_weights, test_input)
  io.println("Test inference completed")
  let grad_list = list.map(list.range(0, workers - 1), fn(idx) {
    matrix_random(10, 10, seed + idx + 10000)
