pub fn vector_subtract(a: List(Float), b: List(Float)) -> List(Float) {
  list.zip(a, b)
  |> list.map(fn(pair) { pair.0 -. pair.1 })
}

pub fn gram_schmidt_qr(matrix: Matrix) -> Matrix {
  let num_cols = case matrix.rows < matrix.cols {
    True -> matrix.rows
    False -> matrix.cols
  }
  let q_matrix = list.fold(list.range(0, num_cols - 1), matrix_zeros(matrix.rows, num_cols), fn(q_acc, j) {
    let col = get_column(matrix, j)
    let orthogonal_col = list.fold(list.range(0, j - 1), col, fn(v_acc, i) {
      let q_col = get_column(q_acc, i)
      let projection_coeff = vector_dot(col, q_col)
      let projection = vector_scale(q_col, projection_coeff)
      vector_subtract(v_acc, projection)
    })
    let norm = vector_norm(orthogonal_col)
    let normalized_col = case norm >. 0.0001 {
      True -> vector_scale(orthogonal_col, 1.0 /. norm)
      False -> orthogonal_col
    }
    set_column(q_acc, j, normalized_col)
  })
  q_matrix
}

pub fn orthogonal_init(rows: Int, cols: Int, seed: Int) -> Matrix {
  let random_matrix = matrix_random(rows, cols, seed)
  let q_matrix = gram_schmidt_qr(random_matrix)
  case rows == cols {
    True -> q_matrix
    False -> case rows > cols {
      True -> q_matrix
      False -> {
        let full_q = gram_schmidt_qr(matrix_random(cols, rows, seed + 1000))
        let transposed = matrix_transpose(full_q)
        Matrix(rows: rows, cols: cols, data: list.take(transposed.data, rows * cols))
      }
    }
  }
}

pub fn xavier_uniform_init(rows: Int, cols: Int, seed: Int) -> Matrix {
  let limit_squared = 6.0 /. int.to_float(rows + cols)
  let limit = case float.square_root(limit_squared) {
    Ok(l) -> l
    Error(_) -> 1.0
  }
  let random_matrix = matrix_random(rows, cols, seed)
  matrix_scale(random_matrix, limit)
}

pub fn xavier_normal_init(rows: Int, cols: Int, seed: Int) -> Matrix {
  let variance = 2.0 /. int.to_float(rows + cols)
  let std_dev = case float.square_root(variance) {
    Ok(s) -> s
    Error(_) -> 1.0
  }
  let random_matrix = matrix_random(rows, cols, seed)
  matrix_scale(random_matrix, std_dev)
}

pub fn he_init(rows: Int, cols: Int, seed: Int) -> Matrix {
  let variance = 2.0 /. int.to_float(rows)
  let std_dev = case float.square_root(variance) {
    Ok(s) -> s
    Error(_) -> 1.0
  }
  let random_matrix = matrix_random(rows, cols, seed)
  matrix_scale(random_matrix, std_dev)
}

pub fn initialize_embeddings(vocab_size: Int, dim: Int, seed: Int) -> Matrix {
  let sqrt_dim = case float.square_root(int.to_float(dim)) {
    Ok(s) -> s
    Error(_) -> 1.0
  }
  let scale_factor = 1.0 /. sqrt_dim
  let random_matrix = matrix_random(vocab_size, dim, seed)
  matrix_scale(random_matrix, scale_factor)
}

pub fn positional_encoding(seq_length: Int, dim: Int) -> Matrix {
  let data = list.flat_map(list.range(0, seq_length - 1), fn(pos) {
    list.map(list.range(0, dim - 1), fn(i) {
      let pos_f = int.to_float(pos)
      let i_f = int.to_float(i)
      let angle = pos_f /. case float.power(10000.0, 2.0 *. i_f /. int.to_float(dim)) {
        Ok(denom) -> denom
        Error(_) -> 1.0
      }
      case int.is_even(i) {
        True -> case float.sin(angle) {
          Ok(s) -> s
          Error(_) -> 0.0
        }
        False -> case float.cos(angle) {
          Ok(c) -> c
          Error(_) -> 0.0
        }
      }
    })
  })
  Matrix(rows: seq_length, cols: dim, data: data)
}

pub fn layer_norm(matrix: Matrix, epsilon: Float) -> Matrix {
  let row_means = list.map(list.range(0, matrix.rows - 1), fn(row) {
    let row_data = list.map(list.range(0, matrix.cols - 1), fn(col) {
      result.unwrap(matrix_get(matrix, row, col), 0.0)
    })
    list.fold(row_data, 0.0, fn(acc, x) { acc +. x }) /. int.to_float(matrix.cols)
  })
  let row_variances = list.zip(list.range(0, matrix.rows - 1), row_means)
    |> list.map(fn(pair) {
      let row = pair.0
      let mean = pair.1
      let row_data = list.map(list.range(0, matrix.cols - 1), fn(col) {
        result.unwrap(matrix_get(matrix, row, col), 0.0)
      })
      list.fold(row_data, 0.0, fn(acc, x) {
        let diff = x -. mean
        acc +. diff *. diff
      }) /. int.to_float(matrix.cols)
    })
  let normalized_data = list.flat_map(list.range(0, matrix.rows - 1), fn(row) {
    let mean = result.unwrap(list.at(row_means, row), 0.0)
    let variance = result.unwrap(list.at(row_variances, row), 1.0)
    let std_dev = case float.square_root(variance +. epsilon) {
      Ok(s) -> s
      Error(_) -> 1.0
    }
    list.map(list.range(0, matrix.cols - 1), fn(col) {
      let val = result.unwrap(matrix_get(matrix, row, col), 0.0)
      { val -. mean } /. std_dev
    })
  })
  Matrix(rows: matrix.rows, cols: matrix.cols, data: normalized_data)
}

pub fn attention_weights(query: Matrix, key: Matrix, value: Matrix, dim: Int) -> Matrix {
  let scaling_factor = case float.square_root(int.to_float(dim)) {
    Ok(s) -> s
    Error(_) -> 1.0
  }
  let key_transposed = matrix_transpose(key)
  let scores = matrix_multiply(query, key_transposed)
  let scaled_scores = matrix_scale(scores, 1.0 /. scaling_factor)
  let softmax_scores = softmax_matrix(scaled_scores)
  matrix_multiply(softmax_scores, value)
}

pub fn softmax_matrix(matrix: Matrix) -> Matrix {
  let row_maxes = list.map(list.range(0, matrix.rows - 1), fn(row) {
    let row_data = list.map(list.range(0, matrix.cols - 1), fn(col) {
      result.unwrap(matrix_get(matrix, row, col), 0.0)
    })
    result.unwrap(list.reduce(row_data, float.max), 0.0)
  })
  let exp_data = list.flat_map(list.range(0, matrix.rows - 1), fn(row) {
    let max_val = result.unwrap(list.at(row_maxes, row), 0.0)
    list.map(list.range(0, matrix.cols - 1), fn(col) {
      let val = result.unwrap(matrix_get(matrix, row, col), 0.0)
      case float.exponential(val -. max_val) {
        Ok(e) -> e
        Error(_) -> 1.0
      }
    })
  })
  let exp_matrix = Matrix(rows: matrix.rows, cols: matrix.cols, data: exp_data)
  let row_sums = list.map(list.range(0, matrix.rows - 1), fn(row) {
    list.fold(list.range(0, matrix.cols - 1), 0.0, fn(acc, col) {
      acc +. result.unwrap(matrix_get(exp_matrix, row, col), 0.0)
    })
  })
  let normalized_data = list.flat_map(list.range(0, matrix.rows - 1), fn(row) {
    let sum = result.unwrap(list.at(row_sums, row), 1.0)
    list.map(list.range(0, matrix.cols - 1), fn(col) {
      let val = result.unwrap(matrix_get(exp_matrix, row, col), 0.0)
      val /. sum
    })
  })
  Matrix(rows: matrix.rows, cols: matrix.cols, data: normalized_data)
}

pub fn dropout(matrix: Matrix, rate: Float, seed: Int) -> Matrix {
  let keep_prob = 1.0 -. rate
  let scale = 1.0 /. keep_prob
  let new_data = list.index_map(matrix.data, fn(val, idx) {
    let hash = int.bitwise_exclusive_or(seed + idx, idx * 2654435761)
    let rand = int.to_float(int.bitwise_and(hash, 16777215)) /. 16777216.0
    case rand <. keep_prob {
      True -> val *. scale
      False -> 0.0
    }
  })
  Matrix(rows: matrix.rows, cols: matrix.cols, data: new_data)
}

pub fn main() {
  let vocab_size = 10000
  let embedding_dim = 512
  let seed = 42
  let embeddings = initialize_embeddings(vocab_size, embedding_dim, seed)
  io.println("Embeddings initialized: " <> int.to_string(embeddings.rows) <> "x" <> int.to_string(embeddings.cols))
