  let xavier_weights = xavier_uniform_init(embedding_dim, embedding_dim, seed + 200)
  io.println("Xavier weights initialized: " <> int.to_string(xavier_weights.rows) <> "x" <> int.to_string(xavier_weights.cols))
  let he_weights = he_init(embedding_dim, embedding_dim, seed + 300)
  io.println("He weights initialized: " <> int.to_string(he_weights.rows) <> "x" <> int.to_string(he_weights.cols))
  let pos_enc = positional_encoding(100, embedding_dim)
